(function(g){g.DOMPurify={sanitize:function(input){var t=document.createElement("template");t.innerHTML=String(input||"");t.content.querySelectorAll("script,iframe,object,embed,link,style").forEach(function(n){n.remove()});t.content.querySelectorAll("*").forEach(function(n){Array.from(n.attributes).forEach(function(a){if(/^on/i.test(a.name)||/^(src|href)$/i.test(a.name)&&/^\s*(javascript:|data:)/i.test(a.value))n.removeAttribute(a.name)})});return t.innerHTML}}})(window);
